Deutsch:
DROP Table  IF EXISTS dst, src, dstlab, srclab, res;

SELECT datano, var, type, varlab, hash INTO TEMP dst
	FROM public.dsvariable WHERE datano = {DataNo};
SELECT datano, var, type, varlab, hash INTO TEMP src
	FROM public.dsvariable WHERE datano IN (SELECT origin FROM dsorigin WHERE datano = {DataNo});
SELECT datano, var, nv, vallab INTO TEMP dstlab
	FROM public.dslabel WHERE datano = {DataNo};
SELECT datano, var, nv, vallab INTO TEMP srclab
	FROM public.dslabel WHERE datano  IN (SELECT origin FROM dsorigin WHERE datano = {DataNo});


SELECT DISTINCT 'New variable label' AS Art, dst.var, dst.type, dst.varlab, CAST(NULL AS Int) AS nv, NULL AS vallab, src.varlab AS change INTO TEMP res FROM dst LEFT JOIN src on dst.var = src.var WHERE dst.varlab <> src.varlab
UNION SELECT 'New variable' AS Art, dst.var, dst.type, dst.varlab, NULL AS nv, NULL AS vallab, NULL AS change FROM dst LEFT JOIN src on dst.var = src.var WHERE src.var IS NULL
UNION SELECT 'New variable type' AS Art, dst.var, dst.type, dst.varlab, NULL AS nv, NULL AS vallab, src.type AS change FROM dst LEFT JOIN src on dst.var = src.var WHERE dst.type <> src.type
UNION SELECT 'New variable value label' AS Art, dstlab.var, NULL AS type, NULL AS varlab, dstlab.nv, dstlab.vallab, srclab.vallab AS change FROM dstlab LEFT JOIN srclab on dstlab.var = srclab.var AND dstlab.nv = srclab.nv WHERE dstlab.vallab <> srclab.vallab;

SELECT * FROM res 
UNION SELECT DISTINCT 'Only data change' AS Art, dst.var, dst.type, dst.varlab, CAST(NULL AS Int) AS nv, NULL AS vallab, NULL AS change FROM dst LEFT JOIN res ON dst.var = res.var LEFT JOIN src ON dst.var = src.var WHERE res.var IS NULL AND dst.hash <> src.hash 
ORDER BY art;

